"use client"

/**
 * Thin wrapper around Magic UI TypingAnimation — passes `words` + pill chrome only.
 * No custom typing logic here; timings use the library defaults / props you pass through.
 */

import { type ComponentProps } from "react"

import { TypingAnimation } from "@/components/ui/typing-animation"
import { cn } from "@/lib/utils"

/** Anything TypingAnimation accepts except children/words */
type MagicTypingPassthrough = Omit<
  ComponentProps<typeof TypingAnimation>,
  "children" | "words"
>

export interface KeywordRotatorProps {
  keywords: readonly string[]
  /**
   * ms to keep the finished phrase readable before deleting (maps to Magic `pauseDelay`;
   * default in library is 1000 — we bump for hero readability).
   */
  pauseDelay?: number
  /** Pill wrapper classes */
  className?: string
  /** Phrase + cursor colour (library applies on the motion root via className merge) */
  textClassName?: string
  /** Extra Magic props: duration (ms/char), typeSpeed, deleteSpeed, showCursor, … */
  typingProps?: Partial<MagicTypingPassthrough>
}

export function KeywordRotator({
  keywords,
  pauseDelay = 4000,
  className,
  textClassName = "text-orange-600",
  typingProps,
}: KeywordRotatorProps) {
  if (keywords.length === 0) return null

  return (
    <span
      className={cn(
        "inline shrink-0 rounded-[3px] bg-amber-50 px-1.5 py-px whitespace-nowrap",
        className,
      )}
      aria-live="polite"
      aria-atomic="true"
    >
      <TypingAnimation
        {...typingProps}
        pauseDelay={pauseDelay}
        words={[...keywords]}
        loop
        as="span"
        startOnView={false}
        className={cn(
          "font-inherit whitespace-nowrap tracking-hero-headline!",
          textClassName,
          typingProps?.className,
        )}
      />
    </span>
  )
}
