"use client";

// app/page.tsx — the main landing page.
// Assembles every section top-to-bottom.
// useState controls the modal — when either form submits, isModalOpen = true.

import { useState } from "react";

import Hero from "@/components/sections/Hero";
import Promise from "@/components/sections/Promise";
import Journey from "@/components/sections/Journey";
import Pillars from "@/components/sections/Pillars";
import FAQ from "@/components/sections/FAQ";
import WaitlistCTA from "@/components/sections/WaitlistCTA";
import Footer from "@/components/layout/Footer";
import WaitlistModal from "@/components/ui/WaitlistModal";

export default function Home() {
  // Shared modal state — passed down to both waitlist forms
  const [isModalOpen, setIsModalOpen] = useState(false);

  const openModal = () => setIsModalOpen(true);
  const closeModal = () => setIsModalOpen(false);

  return (
    <>
      {/* Sections — top to bottom */}
      <Hero onWaitlistSuccess={openModal} />
      <Promise />
      <Journey />
      <Pillars />
      <FAQ />
      <WaitlistCTA onWaitlistSuccess={openModal} />
      <Footer />

      {/* Modal — renders on top of everything when isModalOpen is true */}
      <WaitlistModal isOpen={isModalOpen} onClose={closeModal} />
    </>
  );
}
